请对以下 case 进行三维加权评分。

=== case_id ===
Case-20-notif-aggregate-019

=== 用户原始指令 (query.txt) ===
想要张工作消息聚合卡,横向并排几个群显示未读数,中间嵌个小数据块显示步数,视觉风格想从一张工作照延伸出来,卡内嵌面板块,晚上氛围渐变,跳音乐歌单,静态示例数据,不要特殊状态色,图标用字符

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "想要张工作消息聚合卡,横向并排几个群显示未读数,中间嵌个小数据块显示步数,视觉风格想从一张工作照延伸出来,卡内嵌面板块,晚上氛围渐变,跳音乐歌单,静态示例数据,不要特殊状态色,图标用字符",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "header": {
      "title": {
        "type": "string",
        "description": "卡片标题，表示工作消息聚合对象。",
        "sampleValue": "工作聚合"
      },
      "summary": {
        "type": "string",
        "description": "当前聚合未读总量的短摘要。",
        "sampleValue": "31 未读"
      }
    },
    "groups": {
      "team": {
        "name": {
          "type": "string",
          "description": "第一个工作群的短名称。",
          "sampleValue": "企微"
        },
        "unreadText": {
          "type": "string",
          "description": "第一个工作群的未读数展示文本。",
          "sampleValue": "12"
        }
      },
      "project": {
        "name": {
          "type": "string",
          "description": "第二个工作群的短名称。",
          "sampleValue": "项目"
        },
        "unreadText": {
          "type": "string",
          "description": "第二个工作群的未读数展示文本。",
          "sampleValue": "8"
        }
      },
      "client": {
        "name": {
          "type": "string",
          "description": "第三个工作群的短名称。",
          "sampleValue": "客户"
        },
        "unreadText": {
          "type": "string",
          "description": "第三个工作群的未读数展示文本。",
          "sampleValue": "11"
        }
      }
    },
    "steps": {
      "label": {
        "type": "string",
        "description": "步数数据块的短标签。",
        "sampleValue": "步数"
      },
      "valueText": {
        "type": "string",
        "description": "当前步数数值展示文本。",
        "sampleValue": "6842"
      },
      "unit": {
        "type": "string",
        "description": "步数单位展示文本。",
        "sampleValue": "步"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "音乐歌单跳转入口的短标签，使用字符图标。",
        "sampleValue": "♪ 歌单"
      }
    }
  },
  "assetCandidates": []
}

